const generationScreen=document.getElementById('generation-screen');
function generationView(error){
 const failed=Boolean(error);
 generationScreen.innerHTML=`<div class="generation-page"><div class="generation-brand">轻练 <span>· 为你安排每一步</span></div><section class="generation-card ${failed?'generation-failed':''}"><div class="generation-symbol" aria-hidden="true">${icon(failed?'clipboard':'leaf')}<i></i></div><p class="generation-eyebrow">${failed?'资料已保留':'你的第一份训练计划'}</p><h1 id="generation-title" tabindex="-1">${failed?'这次未能完成生成':'正在从 DeepSeek<br>获取训练计划'}</h1><p id="generation-description">${failed?'可以重新尝试，也可以返回修改资料。确认启用前，不会保存或替换训练计划。':'正在根据你的目标、运动基础和可用器械，安排适合你的训练节奏。'}</p>${failed?`<p class="generation-error" role="alert">${escapeHTML(error.message||'生成失败，请稍后重试')}</p><div class="generation-actions"><button class="primary" data-action="generation-retry">重新尝试</button><button class="secondary" data-action="generation-back">返回修改资料</button></div>`:`<div class="generation-status" role="status" aria-live="polite"><span class="generation-spinner" aria-hidden="true"></span><p id="generation-status-text">正在生成与检查，请稍候…</p></div><div class="generation-notes"><span>${icon('dumbbell')}标准动作库</span><span>${icon('shield')}方案校验</span><span>${icon('clipboard')}完成后先预览</span></div>`}</section><p class="generation-footnote">${failed?'你填写的资料仍在当前页面中。':'请保持页面打开，完成后会自动展示计划预览。<br>复杂方案可能需要更久，必要时会自动修正。'}</p></div>`;
 if(!generationScreen.open)generationScreen.showModal();
 document.getElementById('generation-title').focus();
}
const firstGenerationFlow=createGenerationFlow({
 waiting:()=>generationView(),
 slow:()=>{const status=document.getElementById('generation-status-text');if(status)status.textContent='仍在生成与检查，复杂方案可能需要更久…';},
 complete:()=>{generationScreen.close();initialGeneration=null;document.getElementById('sheet-title')?.focus();},
 failed:error=>generationView(error)
});
generationScreen.addEventListener('cancel',e=>e.preventDefault());
window.addEventListener('beforeunload',e=>{if(firstGenerationFlow.busy){e.preventDefault();e.returnValue='';}});
const weekday=['日','一','二','三','四','五','六'];
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
// Calendar dates and all plan keys follow the user's Asia/Shanghai time zone.
const dateParts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
const part=t=>dateParts.find(p=>p.type===t).value;
const today=new Date(Number(part('year')),Number(part('month'))-1,Number(part('day')),12),todayKey=dateKey(today);
const addDays=(d,n)=>new Date(d.getFullYear(),d.getMonth(),d.getDate()+n,12);
const monday=addDays(today,-((today.getDay()+6)%7));
const shortDate=d=>`${d.getMonth()+1}月${d.getDate()}日`;
const defaults={name:'朋友',height:null,weight:null,age:null,goal:'保持健康',experience:'初学者',days:[0,2,5],duration:35,equipment:'居家 · 徒手',limits:'暂无',diet:'无特殊偏好',reminder:'19:00'};
let state={profile:{...defaults},logs:{},reviews:{},plans:{},drafts:{},sessions:{},snapshots:{},revision:0};
let ready=false,busy=false,loadError='',setupNotice='',capabilities={aiConfigured:false},knowledge=null;
async function loadState(){try{const res=await localFetch('/api/state',{cache:'no-store'});const data=await res.json();if(!res.ok)throw new Error(data.error||'记录服务暂时不可用');state=data.state;capabilities=data.capabilities;knowledge=data.knowledge;for(const [id,item] of Object.entries(data.exercises||{}))taskLibrary[id]={...taskLibrary[id],...item};if(data.preparedProgramAvailable){const activated=await localFetch('/api/programs/activate-prepared',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:state.revision,requestId:uniqueId()})});const result=await activated.json();if(activated.ok){state=result.state;setupNotice='';}else{setupNotice=result.error||'已准备计划，暂未启用；原记录保留';if(activated.status===409){const latest=await localFetch('/api/state',{cache:'no-store'});if(latest.ok)state=(await latest.json()).state;}}}ready=true;loadError='';render();}catch(e){ready=false;loadError='训练记录暂未加载，请重试';render();}}
async function mutate(path,body){if(!ready)throw new Error('请等待训练记录加载完成');if(busy)throw new Error('正在保存，请稍候');busy=true;try{const response=await localFetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,revision:state.revision,requestId:uniqueId()})});const data=await response.json();if(!response.ok){if(response.status===409)await loadState();throw new Error(data.error||'保存失败，请稍后重试');}state=data.state;render();return state;}finally{busy=false;}}
function recordDescription(key,id){const r=state.logs[key]?.[id];if(!r?.done)return '';const source={checkin:'快捷打卡',manual:'手动补记',app_timer:'应用计时'}[r.source]||'手动记录',side=tasksFor(key).find(t=>t.id===id)?.measurement?.sides===2?'每侧 ':'';const extra=r.actual?Object.entries(r.actual).map(([key,value])=>({distanceKm:value+' 公里',sets:value+' 组',reps:side+value+' 次',holdSeconds:side+value+' 秒 / 组',rounds:value+' 轮',workSeconds:'运动段 '+value+' 秒',recoverySeconds:'恢复段 '+value+' 秒'}[key]||'')).filter(Boolean).join(' · '):'';return `${source}${extra?' · '+extra:''} · ${r.minutes==null?'时长未填写':r.minutes+' 分钟'}`;}
let page=['today','plan','mine'].includes(location.hash.slice(1))?location.hash.slice(1):'today';
const expandedCycles=new Set();
let weekOffset=0,selectedKey=todayKey,activeTask=null,modalFocus=null,toastTimeout,timerInterval=null,timerEnd=0,timerRemaining=0,restDefault=60;
const taskLibrary={
 warmup:{id:'warmup',name:'热身活动',minutes:5,meta:'5 分钟 · 动态热身',type:'run',steps:['原地轻松踏步，逐渐活动肩膀、手臂和脚踝。','从小幅度的抬膝、髋部活动开始，让身体慢慢进入运动状态。','全程保持自然呼吸，按舒适节奏完成。'],note:'热身从轻松活动开始；若有疼痛、头晕或明显不适，请停止训练。'},
 squat:{id:'squat',name:'徒手深蹲',minutes:7,meta:'3 组 × 12 次 · 组间休息 60 秒',type:'dumbbell',steps:['双脚自然分开，与肩同宽，脚尖略向外，脚掌稳定着地。','吸气，臀部向后下方移动，膝盖与脚尖方向一致，蹲到舒适深度。','呼气，脚掌均匀发力站起。保持动作可控，不急着增加速度。'],note:'膝盖或腰部出现疼痛时停止动作；可扶稳固椅背，减小下蹲幅度。'},
 upper:{id:'upper',name:'上肢力量',minutes:15,meta:'15 分钟 · 3 个动作',type:'dumbbell',steps:['靠墙俯卧撑：双手撑墙，身体保持直线，缓慢屈肘再推回。按能力完成 2 组。','站姿肩胛后收：手臂自然放松，将肩胛轻轻向后靠拢，再缓慢放松。','跪姿支撑：双手与肩同宽，稳定躯干，保持自然呼吸。组间充分休息。'],note:'优先保证姿势和呼吸。手腕或肩部不适时暂停，并选择适合自己的替代动作。'},
 stretch:{id:'stretch',name:'拉伸放松',minutes:8,meta:'8 分钟 · 全身拉伸',type:'stretch',steps:['从小腿、大腿后侧开始，在舒适范围内轻柔拉伸。','继续放松臀部、胸部和肩部，每个姿势保持自然呼吸。','缓慢进入和退出姿势，左右两侧均衡完成。'],note:'以轻微牵拉感为宜，不弹震、不憋气，不强行追求幅度。'},
 running:{id:'running',name:'轻松跑走',minutes:20,meta:'20 分钟 · 跑走交替',type:'run',steps:['先从步行开始，逐渐过渡到舒适的慢跑。','以仍能轻松说话的强度进行，按体感交替跑步与步行。','结束前逐步放慢，记录实际时间和距离。'],note:'选择平坦安全的路线。出现疼痛或明显不适时停止，不强行完成目标。'}
};
function weekReviewFor(d){const start=addDays(d,-((d.getDay()+6)%7));return state.reviews[dateKey(start)];}
function programDay(key){return state.program?.cycles.flatMap(c=>c.days).find(d=>d.date===key);}
function currentCycle(){if(!state.program)return 0;return Math.max(0,Math.min(3,Math.floor((Date.parse(todayKey)-Date.parse(state.program.start))/604800000)));}
function tasksFor(key){return taskList(state,key);}
function prescription(t){return taskPrescription(t,state.program);}
function stageCard(selectedIndex=currentCycle()){const p=state.program;if(!p)return `<section class="card stage-card"><div class="card-head">${icon('leaf')}<h2>开启你的 28 天</h2></div><p>每天按计划行动，每 7 天回顾一次。训练、动作讲解与家常餐饮都放在这里。</p><button class="primary" data-action="program-setup">开始 28 天居家阶段</button></section>`;const index=selectedIndex,current=currentCycle(),day=Math.max(1,Math.min(28,Math.floor((Date.parse(todayKey)-Date.parse(p.start))/86400000)+1));return `<section class="card stage-card"><div class="stage-top"><span>28 天居家减脂 · 回归训练</span><strong>第 ${day}<small> / 28 天</small></strong></div><div class="stage-track">${p.cycles.map((c,i)=>`<button aria-label="查看第 ${i+1} 周期" class="${i===index?'active':''}" data-action="cycle" data-index="${i}"><span>周期 ${i+1}</span><small>${escapeHTML(c.theme)}</small></button>`).join('')}</div><p>${shortDate(new Date(p.start+'T12:00:00'))}—${shortDate(new Date(p.end+'T12:00:00'))} · 当前第 ${current+1} 周期${programDay(todayKey)?' · '+escapeHTML(programDay(todayKey).title):''}</p></section>`;}
function logsFor(key){if(!state.logs[key]||typeof state.logs[key]!=='object')state.logs[key]={};return state.logs[key];}
function isDone(key,id){return !!state.logs[key]?.[id]?.done;}
function dayStats(key){const tasks=tasksFor(key),done=tasks.filter(t=>isDone(key,t.id)),minutes=tasks.reduce((n,t)=>n+t.minutes,0),actual=done.reduce((n,t)=>n+(Number(state.logs[key][t.id].minutes)||0),0),missing=done.filter(t=>state.logs[key][t.id].minutes===null||state.logs[key][t.id].minutes===undefined).length;return{tasks,done,minutes,actual:Math.round(actual*10)/10,missing,pct:tasks.length?Math.round(done.length/tasks.length*100):0};}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),2600);}
function ring(pct){const length=251.33;return `<div class="progress-ring" aria-label="完成 ${pct}%"><svg viewBox="0 0 91 91"><circle cx="45.5" cy="45.5" r="40" stroke="#edf0f6"/><circle cx="45.5" cy="45.5" r="40" stroke="#3d78fa" stroke-dasharray="${length}" stroke-dashoffset="${length*(1-pct/100)}"/></svg><strong>${pct}%</strong></div>`;}
function header(title,eyebrow,right){return `<header><div>${eyebrow?`<p class="eyebrow">${escapeHTML(eyebrow)}</p>`:''}<h1>${title}</h1></div>${right||''}</header>`;}
function render(){document.title=`${{today:'今天',plan:'计划',mine:'我的'}[page]} · 轻练`;nav.innerHTML=[['today','home','今天'],['plan','calendar','计划'],['mine','user','我的']].map(([key,i,label])=>`<button class="nav-item ${page===key?'active':''}" data-action="navigate" data-page="${key}" aria-current="${page===key?'page':'false'}">${icon(i)}<span>${label}</span></button>`).join('');app.innerHTML=`<div class="page">${!ready?`<div class="sync-banner">${loadError||'正在读取本机记录…'}${loadError?'<button class="link" data-action="reload">重试</button>':''}</div>`:setupNotice?`<div class="sync-banner">${escapeHTML(setupNotice)}</div>`:''}${ready&&!state.program?onboardingPage():page==='today'?todayPage():page==='plan'?planPage():minePage()}</div>`;}
const illustratedTasks=new Set(['chair_squat','supported_squat','wall_press','row_4kg','bridge','dead_bug','bird_dog','calf_raise','mobility','relax','walk_easy','cool_walk']);
function exerciseArt(t,key,detail=false){if(t.prescription){if(!t.image)return '';const picture=`<img src="${escapeHTML(t.image)}" width="400" height="400" loading="lazy" decoding="async" alt="${escapeHTML(t.name)}动作示意">`;return detail?`<figure class="detail-art standard-art">${picture}<figcaption>标准动作示意 · 结合文字步骤</figcaption></figure>`:'';}const id=t.id==='squat'?'chair_squat':t.id==='stretch'?'relax':t.id;if(!illustratedTasks.has(id))return '';const picture=`<img src="./assets/exercises/${id}.svg" width="440" height="232" loading="lazy" decoding="async" alt="${escapeHTML(t.name)}的起始姿势、动作过程和关键要点">`;return detail?`<figure class="detail-art">${picture}<figcaption>动作要点示意 · 结合文字说明完成</figcaption></figure>`:`<button class="exercise-art" data-action="task" data-key="${key}" data-id="${t.id}" aria-label="查看${escapeHTML(t.name)}动作要点">${picture}</button>`;}
function todayPlanHero(){const p=state.program,s=dayStats(todayKey);if(!p)return stageCard();const elapsed=Math.max(0,Math.min(27,Math.floor((Date.parse(todayKey)-Date.parse(p.start))/86400000))),phrases=['每一次开始，都在靠近更好的自己。','按自己的节奏，稳稳向前。','恢复得好，也是今天的进步。','把动作做好，比做得更多更重要。','给身体一点时间，给坚持一点耐心。','今天的小小坚持，会慢慢积累成变化。','好好休息，准备下一次出发。'];return `<section class="card today-hero"><div class="hero-kicker"><span>${escapeHTML(p.title)}</span><span class="cycle-pill">周期 ${currentCycle()+1} / ${p.cycleCount}</span></div><p class="encouragement">${phrases[elapsed%phrases.length]}</p><p class="hero-context">第 ${elapsed+1} / 28 天 · ${escapeHTML(programDay(todayKey)?.title||'恢复与复盘')}</p><div class="today-numbers"><div><strong>${s.tasks.length?`${s.done.length}<small>/${s.tasks.length}</small>`:programDay(todayKey)?.kind==='pending'?'待生成':'休息'}</strong><span>${dayStats(todayKey).tasks.length?'今日已完成':programDay(todayKey)?.kind==='pending'?'本周期待生成':'今天无需补训练量'}</span></div><div><strong>${s.actual}<small> 分钟</small></strong><span>实际已记录</span></div><div><strong>${s.minutes||'—'}<small>${s.minutes?' 分钟':''}</small></strong><span>今日计划</span></div></div>${s.tasks.length?`<div class="thin-progress" role="progressbar" aria-label="今日任务完成率" aria-valuenow="${s.pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${s.pct}%"></i></div>`:''}${s.missing?`<p class="completion-note">${s.missing} 项已完成任务尚未填写实际时长</p>`:''}</section>`;}
function todayPage(){const day=programDay(todayKey),s=dayStats(todayKey);return `${header('今天',`${shortDate(today)} 周${weekday[today.getDay()]}`,`<button class="avatar" aria-label="查看个人信息" data-action="navigate" data-page="mine">${escapeHTML(state.profile.name.slice(0,1))}</button>`)}${todayPlanHero()}${activeSessionCard()}<div class="section-head"><h2>${escapeHTML(day?.title||'今日训练')}</h2><span>${s.tasks.length?`${s.tasks.length} 项 · 约 ${s.minutes} 分钟`:'放松一下'}</span></div>${day?`<p class="day-guidance">${escapeHTML(day.note)}</p>`:''}<div class="today-actions">${s.tasks.map(t=>taskRow(t,todayKey,false)).join('')||`<section class="card"><div class="empty-state">${icon('leaf')}${day?.kind==='pending'?'本周期详细安排尚未生成。<br>先填写上一周期反馈，再准备本周期计划。':state.program?'今天没有必须完成的训练。<br>好好恢复，把身体感受记录下来。':'完善个人资料，准备你的第一份计划。'}</div>${day?.kind==='pending'?`<button class="primary" data-action="generate-cycle" data-index="${currentCycle()}">准备本周期计划</button>`:!state.program?'<button class="primary" data-action="program-setup">准备我的计划</button>':''}</section>`}</div><section class="card meal-card"><div class="card-head">${icon('food')}<h2>今日餐饮</h2><button class="link" data-action="meal" data-meal="午餐" data-key="${todayKey}">查看 ${icon('chevron')}</button></div>${day?`<div class="meal-preview"><p><span>早</span>${escapeHTML(day.meal.breakfast)}</p><p><span>午</span>${escapeHTML(day.meal.lunch)}</p><p><span>晚</span>${escapeHTML(day.meal.dinner)}</p></div>`:'<p class="meal-note">均衡搭配，轻松吃好每一餐</p>'}<div class="meal-tags">${['早餐','午餐','晚餐'].map(m=>`<button data-action="meal" data-meal="${m}" data-key="${todayKey}">${m}</button>`).join('')}</div></section>${reviewCard()}`;}
function taskRow(t,key,showArt=true){return actionCard({task:t,date:key,done:isDone(key,t.id),future:key>todayKey,dose:prescription(t),record:recordDescription(key,t.id),art:showArt?exerciseArt(t,key):'',icon});}
function reviewCard(){const p=state.program,cycle=p?.cycles[currentCycle()],next=cycle?dateKey(addDays(new Date(cycle.end+'T12:00:00'),1)):dateKey(addDays(monday,7)),review=state.reviews[next];return `<section class="card review-card">${icon('clipboard')}<div><h3>${review?'周期反馈已记录':'每 7 天身体反馈'}</h3><p>${cycle?`${shortDate(new Date(cycle.end+'T12:00:00'))}复盘 · `:''}完成、疲劳与身体感受</p></div><button class="pill" data-action="review">${review?'查看 / 更新':'去记录'}</button></section>`;}
function durationMarkup(minutes){const d=durationParts(minutes);return `${d.hours?`${d.hours}<small>小时</small>`:''}${d.minutes||!d.hours?`${d.minutes}<small>分钟</small>`:''}`;}
function durationText(minutes){const d=durationParts(minutes);return `${d.hours?d.hours+'小时':''}${d.minutes||!d.hours?d.minutes+'分钟':''}`;}
function cycleOverview(c,index){const canGenerate=index>0&&c.end>=todayKey&&c.start<=dateKey(addDays(today,7))&&(c.status!=='confirmed'||c.start>=todayKey);return cycleCard({cycle:c,index,current:currentCycle(),expanded:expandedCycles.has(index),today:todayKey,canGenerate,hasFeedback:!!state.reviews[c.start],formatDuration:durationText,icon});}
function trainingPrinciples(){const sources=state.program?.sources||knowledge?.sources||[];return `<section class="card principles-card"><div class="card-head">${icon('shield')}<h2>原则与依据</h2></div><div class="principle-row"><span>01</span><p><strong>从恢复规律开始</strong>${state.program?.reason?escapeHTML(state.program.reason):'每周期 2 次力量、2 次轻松跑走，搭配恢复活动与休息。'}</p></div><div class="principle-row"><span>02</span><p><strong>按身体反馈调整</strong>每 7 天回顾疲劳、疼痛与完成情况，再生成下一周期预览并确认。</p></div><div class="principle-row"><span>03</span><p><strong>看实际记录与趋势</strong>打卡不推算训练时长，计时不直接换算减脂公斤数。</p></div><details class="reference-details"><summary>查看参考资料 ${icon('chevron')}</summary>${sources.map(source=>`<a href="${escapeHTML(source.url)}" target="_blank" rel="noopener"><span>${escapeHTML(source.title)}</span><small>${escapeHTML(source.scope)}</small>${icon('arrow')}</a>`).join('')}<a href="https://www.niddk.nih.gov/health-information/weight-management/body-weight-planner" target="_blank" rel="noopener"><span>NIDDK · 体重变化与饮食、活动规划</span><small>减脂预期的评估原则</small>${icon('arrow')}</a></details><p class="principles-note">对话整理的自主训练参考；动作图用于说明要点，具体计划尚未经过独立专业审核。</p></section>`;}
function planPage(){if(!state.program)return `${header('计划','从今天开始，慢慢建立节奏')}${stageCard()}${trainingPrinciples()}`;const p=state.program,m=programmeMetrics(p,state.logs,state.snapshots),reviewDate=p.cycles[currentCycle()].end;return `${header('计划',`${shortDate(new Date(p.start+'T12:00:00'))}—${shortDate(new Date(p.end+'T12:00:00'))} · 28 天 / 4 个周期`)}<section class="card programme-overview"><div class="overview-title"><span class="overview-icon">${icon('calendar')}</span><div><h2>${escapeHTML(p.title)}</h2><p>${p.migratedFromLegacy?'保留原阶段安排 · 新确认周期采用标准库':p.schemaVersion===2?'已确认 '+m.confirmedCycles+' / 4 个周期 · 后续结合反馈生成':'原有计划继续保留，可按周期反馈调整未来安排。'}</p></div></div><div class="overview-numbers"><div><span>${m.pendingCycles?'已确认计划时长':'计划总时长'}</span><strong>${durationMarkup(m.plannedMinutes)}</strong></div><div><span>${m.pendingCycles?'已确认任务进度':'整体进度'}</span><strong>${m.pct}<small>%</small></strong></div></div><div class="thin-progress overall" role="progressbar" aria-label="已确认任务完成率" aria-valuenow="${m.pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${m.pct}%"></i></div><p class="overall-caption">${m.done} / ${m.tasks} 项完成 · 已记录 ${m.actualMinutes} 分钟${m.missingMinutes?` · ${m.missingMinutes} 项时长未填`:''}${m.actualDistanceKm?' · 实际跑步 '+m.actualDistanceKm+' 公里':''}</p><div class="fatloss-outlook"><div>${icon('target')}<span>${state.profile.goal==='减脂塑形'?'预计减脂效果':'训练效果预期'}</span><strong>待首周期评估</strong></div><p>${state.profile.goal==='减脂塑形'?'先建立运动习惯、维持力量，观察体重与腰围趋势。具体公斤数需结合饮食和执行情况评估。':'观察执行率、动作控制与身体感受，每周期反馈后再评估。'}</p><span class="outlook-meta">${state.profile.weight?`当前体重记录 ${escapeHTML(state.profile.weight)} kg · `:''}${shortDate(new Date(reviewDate+'T12:00:00'))}周期反馈</span></div></section><div class="section-head"><h2>四个周期，稳步推进</h2><span>${m.activeDays} 个活动日 · ${m.knownDays-m.activeDays} 个休息日${m.pendingCycles?' · '+m.pendingCycles+' 周期待生成':''}</span></div>${m.cycles.map(cycleOverview).join('')}${trainingPrinciples()}`;}
function settingRow(label,value,name,field){return `<button class="setting-row" data-action="edit" data-field="${field}" aria-label="编辑${label}">${icon(name)}<span class="label">${label}</span><span class="value">${escapeHTML(value)}</span>${icon('chevron')}</button>`;}
function minePage(){const p=state.profile;return `${header('我的','每一天，都更靠近自己',`<button class="icon-button" aria-label="提醒设置" data-action="edit" data-field="reminder">${icon('settings')}</button>`)}<section class="card"><div class="profile-top"><div class="avatar large">${escapeHTML(p.name.slice(0,1))}</div><div class="profile-name"><h2>${escapeHTML(p.name)}</h2><p>每一点坚持，都算数</p></div><button class="edit-pill" data-action="edit" data-field="basic">${icon('edit')}编辑</button></div><div class="profile-metrics">${[[p.height,'cm','身高'],[p.weight,'kg','体重'],[p.age,'岁','年龄']].map(([n,u,l])=>`<div class="profile-metric"><strong>${escapeHTML(n??'—')}</strong><small>${u}</small><p>${l}</p></div>`).join('')}</div></section><section class="card settings-card"><h2>健身档案</h2>${settingRow('健身目标',p.goal,'target','goal')}${settingRow('运动基础',p.experience,'chart','experience')}${settingRow('跑步基础',p.runningKm==null?'未填写':p.runningKm+' 公里','run','basic')}${settingRow('训练时间',`每天可用 · 最多 ${p.duration} 分钟`,'clock','schedule')}${settingRow('场地与器械',p.equipment,'layers','equipment')}</section><section class="card settings-card"><h2>偏好与健康</h2>${settingRow('身体限制',p.limits,'shield','limits')}${settingRow('饮食偏好',p.diet,'food','diet')}${settingRow('提醒设置',p.reminder==='关闭'?'已关闭':`每日 ${p.reminder}`,'bell','reminder')}</section>${backupCard()}${resetPlanCard()}<p class="profile-caption">每个周期反馈后，再一起调整计划<br>真实记录从零开始 · 仅保存在当前浏览器<br>${state.program?'28 天阶段 · 每 7 天反馈调整':'在对话中告诉我资料，一起完善计划'}<br><button class="link" data-action="record-history">查看记录修改历史</button></p>`;}
function navigate(next){if(!['today','plan','mine'].includes(next))return;page=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'});}
function openSheet(title,body){modalFocus=document.activeElement;document.getElementById('sheet-content').innerHTML=`<div class="handle"></div><div class="sheet-head"><h2 id="sheet-title" tabindex="-1">${title}</h2><button class="icon-button" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}`;if(!sheet.open)sheet.showModal();document.body.style.overflow='hidden';}
function stopTimer(){clearInterval(timerInterval);timerInterval=null;timerEnd=0;}
function closeSheet(){if(generationScreen.open)return;if(aiRequestController){aiRequestController.abort();aiRequestController=null;}sheet.close();document.body.style.overflow='';stopTimer();activeTask=null;if(modalFocus?.isConnected)modalFocus.focus();}
sheet.addEventListener('cancel',e=>{e.preventDefault();closeSheet();});sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
async function toggleTask(key,id){if(!tasksFor(key).some(t=>t.id===id))return;const done=!isDone(key,id);await mutate('records',{date:key,id,done,minutes:null,source:'checkin'});toast(done?'已打卡，实际时长可稍后补记':'已撤销完成状态，修改历史保留');}
function taskDetail(key,id){stopTimer();const t=tasksFor(key).find(t=>t.id===id);if(!t)return;activeTask={key,id};timerRemaining=t.restSeconds||60;restDefault=timerRemaining;const done=isDone(key,id),future=key>todayKey;const clock=String(Math.floor(timerRemaining/60)).padStart(2,'0')+':'+String(timerRemaining%60).padStart(2,'0');openSheet(t.name,`<div class="detail-badge">${icon(t.type)}${escapeHTML(t.target||'基础练习')}</div><div class="exercise-dose"><h3>${escapeHTML(prescription(t))}</h3><p>${t.prescription?'标准动作库 '+escapeHTML(t.libraryVersion):escapeHTML(t.load||'按舒适幅度完成')} · ${t.minutes==null?'预计时长未填写':'预计 '+durationText(t.minutes)}</p></div>${exerciseArt(t,key,true)}${sessionControls(key,id)}${done?`<button class="secondary blue" style="width:100%;margin-bottom:18px" data-action="edit-record" data-key="${key}" data-id="${id}">补记 / 修改训练记录</button>`:''}<h3>怎么做</h3><ol class="steps">${(t.steps||['按舒适节奏完成，并记录实际情况。']).map(step=>`<li>${escapeHTML(step)}</li>`).join('')}</ol>${t.keyPoints?`<div class="detail-section"><h3>动作要点</h3><p>${escapeHTML(t.keyPoints)}</p></div>`:''}${t.breathing?`<div class="detail-section"><h3>呼吸</h3><p>${escapeHTML(t.breathing)}</p></div>`:''}${t.errors?`<div class="detail-section"><h3>注意这些错误</h3><ul>${t.errors.map(e=>`<li>${escapeHTML(e)}</li>`).join('')}</ul></div>`:''}${t.alternative?`<div class="detail-section"><h3>太难时怎么换</h3><p>${escapeHTML(t.alternative)}</p></div>`:''}<div class="note">${escapeHTML(t.note||'有疼痛或不适时停止相关动作。')}</div>${t.restSeconds?`<div class="timer" id="timer">${clock}</div><p class="timer-label">组间休息 · ${t.restSeconds} 秒</p><button class="secondary blue" style="width:100%" data-action="timer" id="timer-button">${icon('play')}开始休息计时</button>`:''}<div class="sheet-actions"><button class="secondary" data-action="close">稍后再练</button><button class="primary" data-action="finish-task" data-key="${key}" data-id="${id}" ${future?'disabled':''}>${icon(done?'close':'check')}${future?'尚未到训练日期':done?'撤销完成':'记录完成'}</button></div><p class="health-line">对话整理的自主训练参考。动作不适合时可以跳过，并在周期反馈中说明。</p>`);}
function startTimer(){if(timerInterval){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));stopTimer();const b=document.getElementById('timer-button');if(b)b.innerHTML=`${icon('play')}继续计时`;return;}if(timerRemaining<=0)timerRemaining=restDefault;timerEnd=Date.now()+timerRemaining*1000;const b=document.getElementById('timer-button');if(b)b.innerHTML=`${icon('pause')}暂停计时`;function tick(){const remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerRemaining=remaining;const el=document.getElementById('timer');if(el)el.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if(!remaining){stopTimer();if(b)b.innerHTML=`${icon('play')}再计时 ${restDefault} 秒`;toast('休息结束，按自己的节奏继续');}}timerInterval=setInterval(tick,250);tick();}
const meals={早餐:[['在家吃','燕麦或全麦面包，搭配鸡蛋、牛奶或无糖豆浆，再加一份水果。'],['方便替换','不吃乳制品可以选无糖豆浆；主食也可以换成杂粮粥。']],午餐:[['在家吃','一份米饭或杂粮饭，搭配鱼、鸡肉或豆腐，以及两种蔬菜。'],['外卖怎么选','选择有主食、蛋白质和蔬菜的套餐，酱汁分开放，按饥饱感调整分量。']],晚餐:[['在家吃','杂粮饭或薯类，搭配豆腐、瘦肉或鱼，以及一份熟蔬菜。'],['训练之后','正常吃好一餐；不用为了打卡刻意少吃，也不需要把训练当作多吃的补偿。']]};
function mealDetail(meal,key=todayKey){const m=meals[meal]?meal:'午餐',day=programDay(key),field={早餐:'breakfast',午餐:'lunch',晚餐:'dinner'}[m];openSheet(`${shortDate(new Date(key+'T12:00:00'))} · 餐饮建议`,`<p class="sheet-intro">${escapeHTML(state.profile.diet)} · 家常做饭，三餐规律</p><div class="meal-tabs">${Object.keys(meals).map(n=>`<button data-action="meal" data-meal="${n}" data-key="${key}" class="${n===m?'active':''}">${n}</button>`).join('')}</div>${day?`<div class="meal-detail"><h3>${m}搭配</h3><p>${escapeHTML(day.meal[field])}</p></div><div class="meal-detail"><h3>份量与替换</h3><p>正餐保留蛋白质、蔬菜和主食。肉、鱼、虾可换鸡蛋或豆腐；米饭可换杂粮、玉米或薯类。按饥饱感调整，不用省略主食。</p></div><p class="health-line">${escapeHTML(day.mealNote)} 不根据运动计时推算“可以多吃多少”。如出现持续乏力或饥饿，及时反馈。</p>`:meals[m].map(([title,desc])=>`<div class="meal-detail"><h3>${title}</h3><p>${desc}</p></div>`).join('')}`);}
const input=(name,label,value,type='text',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${escapeHTML(value)}" ${attrs}></label>`;
const select=(name,label,value,options)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(v=>`<option ${v===value?'selected':''}>${escapeHTML(v)}</option>`).join('')}</select></label>`;
function editProfile(field){const p=state.profile;let fields='',title='编辑个人资料';if(field==='basic'){fields=input('name','怎么称呼你',p.name,'text','required maxlength="12" autocomplete="nickname"')+`<div class="field-grid">${input('height','身高 / cm',p.height,'number','required min="80" max="250" step="0.1" inputmode="decimal"')}${input('weight','体重 / kg',p.weight,'number','required min="25" max="350" step="0.1" inputmode="decimal"')}</div>`+input('age','年龄',p.age,'number','required min="18" max="100" step="1" inputmode="numeric"')+input('runningKm','目前可连续跑步 / 公里（选填）',p.runningKm??'','number','min="0" max="100" step="0.001" inputmode="decimal"');}
else if(field==='goal'){title='健身目标';fields=select('goal','选择你的主要目标',p.goal,['减脂塑形','增肌力量','提升体能','保持健康']);}
else if(field==='experience'){title='运动基础';fields=select('experience','目前的训练经验',p.experience,['初学者','有一定基础','规律训练']);}
else if(field==='schedule'){title='训练时间';fields='<label class="field"><span>每周哪些天方便训练？</span></label><div class="day-checkboxes">'+Array.from({length:7},(_,i)=>`<label><input name="days" type="checkbox" value="${i}" ${p.days.includes(i)?'checked':''}><span>周${weekday[(i+1)%7]}</span></label>`).join('')+'</div><div style="height:20px"></div>'+input('duration','每次可用时间 / 分钟',p.duration,'number','required min="10" max="120" step="5" inputmode="numeric"')+'<p class="health-line">保存后已有计划保留。在“计划”中重新生成并确认，才会应用新安排。</p>';}
else if(field==='equipment'){title='场地与器械';fields=select('equipment','平时在哪里训练？',p.equipment,EQUIPMENT_OPTIONS)+'<p class="health-line">器械偏好用于选择标准动作；改变资料后，已有计划保持原样。</p>';}
else if(field==='limits'){title='身体限制';fields=`<label class="field"><span>伤病、疼痛或运动限制</span><textarea name="limits" maxlength="200" required>${escapeHTML(p.limits)}</textarea></label><p class="health-line">体验版会记录你的反馈；如有疼痛，不要继续执行相关动作，请先确认适合自己的运动方式。</p>`;}
else if(field==='diet'){title='饮食偏好';fields=input('diet','口味、忌口与过敏信息',p.diet,'text','required maxlength="100"');}
else{field='reminder';title='提醒设置';fields=input('reminder','希望每天几点运动？',p.reminder==='关闭'?'19:00':p.reminder,'time','required')+`<label class="field"><span>是否开启</span><select name="enabled"><option value="yes" ${p.reminder!=='关闭'?'selected':''}>开启</option><option value="no" ${p.reminder==='关闭'?'selected':''}>关闭</option></select></label><p class="health-line">体验版保存提醒偏好，暂不发送系统通知。</p>`;}
openSheet(title,`<form id="profile-form" data-field="${field}">${fields}<div class="sheet-actions"><button type="button" class="secondary" data-action="close">取消</button><button type="submit" class="primary">保存修改</button></div></form>`);}
function reviewForm(cycleIndex=currentCycle()){const target=state.program?.cycles[cycleIndex+1]?.start,previous=target?state.reviews[target]:null;openSheet('每周身体反馈',`<p class="sheet-intro">回顾第 ${cycleIndex+1} 周期；反馈保存后，再生成下一周期预览。</p><form id="review-form" data-cycle="${cycleIndex}">${input('weight','当前体重 / kg',previous?.weight||state.profile.weight,'number','required min="25" max="350" step="0.1" inputmode="decimal"')}${select('difficulty','本周训练感觉如何？',previous?.difficulty||'强度合适',['偏轻松','强度合适','有些吃力'])}${select('recovery','身体恢复情况',previous?.recovery||'恢复良好',['恢复良好','疲劳较明显','有疼痛或不适'])}${input('note','补充记录（仅保存在本机，选填）',previous?.note||'','text','maxlength="150"')}<div class="sheet-actions"><button type="button" class="secondary" data-action="close">稍后填写</button><button type="submit" class="primary">保存反馈</button></div></form>`);}
function planCard(start){const plan=state.plans[start];return `<section class="card plan-origin"><div class="card-head">${icon('clipboard')}<h3>${plan?'计划已由你确认':'还没有本周计划'}</h3><button class="link" data-action="generate-plan" data-start="${start}">${plan?'调整':'生成'}</button></div><p>${plan?`${plan.engine==='ai'?'AI 参考草稿':'规则参考草稿'} · 待专业审核`:'先完善个人信息，再生成训练参考草稿'}</p>${plan?`<p class="small muted">${escapeHTML(plan.reason)}</p>`:''}<button class="link" data-action="knowledge">查看内容依据与审核状态</button></section>`;}
function programSetup(){const p=state.profile;openSheet('填写资料，生成我的计划',`<p class="sheet-intro">根据你的目标、运动基础、器械、训练日期和时间上限组合 28 天基础参考，不会把可用时间自动填满。</p><form id="program-form" novalidate>${aiGenerationFields()}${input('start','开始日期',todayKey,'date','required')}<div class="field-grid">${input('age','年龄',p.age,'number','required min="18" max="100" step="1"')}${input('height','身高 / cm',p.height,'number','required min="80" max="250" step="0.1"')}</div><div class="field-grid">${input('weight','体重 / kg',p.weight,'number','required min="25" max="350" step="0.1"')}${input('duration','每天可用时间上限 / 分钟',p.duration,'number','required min="10" max="120" step="1" inputmode="numeric"')}</div>${select('goal','主要目标',p.goal,['减脂塑形','增肌力量','提升体能','保持健康'])}${select('experience','运动基础',p.experience,['初学者','有一定基础','规律训练'])}${input('runningKm','目前可连续跑步 / 公里（选填，不能跑填 0）',p.runningKm??'','number','min="0" max="100" step="0.001" inputmode="decimal"')}${select('equipment','场地与器械',p.equipment,EQUIPMENT_OPTIONS)}${trainingDaysField()}${input('background','最近训练与跑步情况（选填）',p.background||'','text','maxlength="200"')}${input('limits','伤病或运动限制（没有填“暂无”）',p.limits,'text','required maxlength="200"')}${input('diet','饮食偏好和就餐方式',p.diet,'text','required maxlength="200"')}<p class="health-line">资料仅保存在当前浏览器。餐饮为通用参考，请核对过敏原。动作内容固定，训练量按本次处方；后续周期反馈后再确认。</p><div class="sheet-actions"><button type="button" class="secondary" data-action="close">取消</button><button type="submit" class="primary">生成我的计划</button></div></form>`);}
function generatePlanForm(start=dateKey(monday)){const next=dateKey(addDays(monday,7));if(![dateKey(monday),next].includes(start)){toast('目前支持生成本周或下周计划');return;}if(!state.profile.age||!state.profile.height||!state.profile.weight){editProfile('basic');toast('请先完善年龄、身高和体重');return;}openSheet('生成训练参考计划',`<p class="sheet-intro">${start===next?'下周':'本周'} · 计划先生成草稿，确认后才会进入待办。</p><div class="review-result"><h3>根据你的时间和条件安排</h3><p>当前动作与规则待专业审核。已有训练记录和进行中的计时不会被新计划覆盖。</p></div><div class="sheet-actions"><button class="primary" data-action="generate-rules" data-start="${start}">生成规则参考草稿</button></div><div class="meal-detail"><h3>AI 个性化编排</h3><p>${capabilities.aiConfigured?'将年龄、身高体重、目标、运动基础、器械条件、身体限制及训练汇总发送给 OpenAI，仅用于生成计划；不发送姓名。':'服务端 AI 密钥尚未配置，当前可以使用规则参考草稿。'}</p>${capabilities.aiConfigured?`<label class="consent-row"><input type="checkbox" id="ai-consent">我同意发送上述必要信息</label>`:''}<button class="secondary blue" style="width:100%;margin-top:12px" data-action="generate-ai" data-start="${start}" ${capabilities.aiConfigured?'':'disabled'}>生成 AI 参考草稿</button></div>`);}
async function generateDraft(start,engine){if(engine==='ai'&&!document.getElementById('ai-consent')?.checked)throw new Error('请先确认向 OpenAI 发送必要信息');const before=new Set(Object.keys(state.drafts));toast(engine==='ai'?'正在生成并校验 AI 草稿…':'正在生成参考草稿…');await mutate('plans/generate',{start,engine,consent:engine==='ai'});const draft=Object.values(state.drafts).find(d=>!before.has(d.id));if(!draft)throw new Error('未找到新草稿，请重试');openSheet('查看计划草稿',`<div class="detail-badge">${icon('clipboard')}${engine==='ai'?'AI 生成':'规则生成'} · 待专业审核</div><h3>${draft.days.filter(d=>d.tasks.length).length} 个训练日</h3><p class="sheet-intro" style="margin-top:10px">${escapeHTML(draft.reason)}</p>${draft.days.map(d=>`<div class="compact-task"><div><p>${escapeHTML(d.date)}</p><span>${d.tasks.length?d.tasks.map(t=>escapeHTML(t.name)).join(' · '):'恢复日'}</span></div><small>${d.tasks.reduce((n,t)=>n+t.minutes,0)} 分钟</small></div>`).join('')}<p class="health-line">动作编号、训练日期、热身放松和时长已通过程序校验；这不代表已经过专业审核。</p><div class="sheet-actions"><button class="secondary" data-action="close">暂不使用</button><button class="primary" data-action="confirm-draft" data-id="${draft.id}">确认使用此计划</button></div>`);}
function showRecordForm(key,id){const t=tasksFor(key).find(t=>t.id===id);if(!t)return;const r=state.logs[key]?.[id];stopTimer();const labels={distanceKm:'实际跑步距离 / 公里',sets:'实际组数',reps:t.measurement?.sides===2?'实际每侧次数':'实际每组次数',holdSeconds:t.measurement?.sides===2?'实际每侧保持时长 / 秒':'实际每组保持时长 / 秒',rounds:'实际轮数',workSeconds:'实际每轮运动 / 秒',recoverySeconds:'实际每轮恢复 / 秒'};const actual=t.prescription?Object.keys(t.prescription).filter(k=>labels[k]).map(k=>input('actual_'+k,labels[k]+'（可留空）',r?.actual?.[k]??'','number',`min="${k==='distanceKm'?'0.001':k==='recoverySeconds'?'0':'1'}" step="${k==='distanceKm'?'0.001':'1'}" inputmode="decimal"`)).join(''):'';openSheet('记录这次训练',`<form id="finish-form" data-key="${key}" data-id="${id}"><p class="sheet-intro">${escapeHTML(t.name)} · 计划 ${escapeHTML(prescription(t))}</p>${actual}${input('minutes','实际训练时长 / 分钟（可留空）',r?.minutes??'','number','min="0.1" max="300" step="0.1" inputmode="decimal"')}<p class="health-line">留空表示实际数据未知，不会自动填写计划值。手动修改后标注为手动补记。</p>${select('effort','这次训练感觉',r?.effort||'强度合适',['偏轻松','强度合适','有些吃力'])}<div class="sheet-actions"><button type="button" class="secondary" data-action="close">取消</button><button class="primary" type="submit">保存完成</button></div></form>`);}
function activeSessionCard(){const session=Object.values(state.sessions).find(s=>!s.endedAt);if(!session)return '';return `<section class="card review-card">${icon('clock')}<div><h3>有一项训练正在计时</h3><p>${escapeHTML(CATALOG_NAME(session.id))} · ${session.paused?'已暂停':'进行中'}</p></div><button class="pill" data-action="${session.date===todayKey?'task':'session-op'}" data-key="${session.date}" data-id="${session.id}" data-session="${session.sessionId}" data-op="discard">${session.date===todayKey?'查看':'停止过期计时'}</button></section>`;}
function CATALOG_NAME(id){return taskLibrary[id]?.name||'训练';}
function sessionControls(key,id){if(key!==todayKey)return '';const session=Object.values(state.sessions).find(s=>!s.endedAt);if(session&&!(session.date===key&&session.id===id))return '<p class="health-line">另一项训练正在计时，请先结束。</p>';return `<div class="workout-timer"><p class="small muted">${session?'本次训练已计时':'记录实际训练时间'}</p>${session?`<strong id="workout-clock" data-start="${session.lastStarted}" data-seconds="${session.seconds}" data-paused="${session.paused}">--:--</strong>`:'<p class="health-line">开始、暂停和结束保存在本机；计时只代表记录过程。</p>'}<div class="sheet-actions">${session?`<button class="secondary blue" data-action="session-op" data-session="${session.sessionId}" data-op="${session.paused?'resume':'pause'}">${session.paused?'继续':'暂停'}</button><button class="primary" data-action="session-op" data-session="${session.sessionId}" data-op="finish">结束并记录</button>`:`<button class="primary" data-action="session-op" data-op="start" data-key="${key}" data-id="${id}">${icon('play')}开始训练计时</button>`}</div>${session?`<button class="link" data-action="session-op" data-op="discard" data-session="${session.sessionId}">放弃本次计时</button>`:''}</div>`;}
setInterval(()=>{const el=document.getElementById('workout-clock');if(!el)return;const seconds=Math.floor(Number(el.dataset.seconds)+(el.dataset.paused==='true'?0:Math.max(0,(Date.now()-Number(el.dataset.start))/1000)));el.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');},500);
function dayDetail(key){const s=dayStats(key),day=programDay(key),date=new Date(key+'T12:00:00');openSheet(`${shortDate(date)} · ${escapeHTML(day?.title||'当天计划')}`,`<p class="sheet-intro">${s.tasks.length?`计划约 ${s.minutes} 分钟 · ${s.done.length}/${s.tasks.length} 项已完成`:'今天是恢复日，给身体一点时间。'}${day?`<br>${escapeHTML(day.note)}`:''}</p><div class="day-modal-list">${s.tasks.map(t=>taskRow(t,key)).join('')}</div><div class="sheet-actions"><button class="secondary blue" data-action="meal" data-meal="午餐" data-key="${key}">当天餐饮</button><button class="primary" data-action="close">知道了</button></div>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,key=b.dataset.key,id=b.dataset.id;
try{switch(a){case'generation-retry':if(initialGeneration&&!firstGenerationFlow.busy)await generateDeepSeekPlan(initialGeneration.form,initialGeneration.data);break;case'generation-back':if(firstGenerationFlow.busy)break;generationScreen.close();initialGeneration=null;document.querySelector('#program-form [type=submit]')?.focus();break;case'ai-plan-confirm':try{b.disabled=true;if(!pendingAI)throw new Error('请先生成方案');await approveAIProgram(browserStorage,pendingAI,pendingAI.revision);pendingAI=null;closeSheet();await loadState();navigate('today');toast('训练方案已确认，历史记录保留');}catch(error){showFormError(document.getElementById('sheet-content'),error.message);}finally{b.disabled=false;}break;case'generate-cycle':cycleGenerateForm(Number(b.dataset.index));break;case'upgrade-restore':openSheet('恢复升级前记录？',`<p class="sheet-intro">将恢复首次升级前的本机备份并替换当前记录。需要保留当前进度时请先导出。</p><div class="sheet-actions"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="upgrade-restore-confirm">确认恢复</button></div>`);break;case'upgrade-restore-confirm':restoreBeforeUpgrade(browserStorage);closeSheet();await loadState();toast('已恢复升级前记录');break;case'reset-plan':confirmPlanReset();break;case'reset-plan-confirm':try{resetTrainingPlan(browserStorage,state.revision);stopTimer();closeSheet();history.replaceState(null,'','#today');location.reload();}catch(error){showResetError(error.message||'重置失败，原记录保留');}break;case'reset-plan-restore':confirmResetRestore();break;case'reset-plan-restore-confirm':try{restoreBeforeReset(browserStorage);stopTimer();closeSheet();history.replaceState(null,'','#today');location.reload();}catch(error){showResetError(error.message||'恢复失败');}break;case'backup-export':exportBackup();break;case'backup-import':document.getElementById('backup-file').click();break;case'backup-confirm':restoreBackup(browserStorage,pendingBackup);pendingBackup=null;closeSheet();await loadState();toast('备份已恢复到当前浏览器');break;case'cycle-toggle':{const index=Number(b.dataset.index);if(expandedCycles.has(index))expandedCycles.delete(index);else expandedCycles.add(index);render();break;}case'program-setup':programSetup();break;case'cycle':{const index=Math.max(0,Math.min(3,Number(b.dataset.index)));weekOffset=index-currentCycle();selectedKey=state.program.cycles[index].start;navigate('plan');break;}case'reload':await loadState();break;case'generate-plan':generatePlanForm(b.dataset.start||dateKey(monday));break;case'generate-rules':await generateDraft(b.dataset.start,'rules');break;case'generate-ai':await generateDraft(b.dataset.start,'ai');break;case'confirm-draft':{const draft=state.drafts[id];await mutate('plans/confirm',{draftId:id});closeSheet();weekOffset=draft.start===dateKey(monday)?0:1;selectedKey=draft.start;navigate('plan');toast('计划已确认，历史记录保留');break;}case'session-op':{const active=activeTask;await mutate('session',{action:b.dataset.op,sessionId:b.dataset.session,date:key,id});if(['finish','discard'].includes(b.dataset.op)){closeSheet();toast(b.dataset.op==='finish'?'计时已保存为实际训练时长':'计时已停止，未生成训练记录');}else if(active)taskDetail(active.key,active.id);break;}case'knowledge':openSheet('内容依据与审核状态',`<div class="detail-badge">待专业审核</div><p class="sheet-intro">本阶段根据对话中的目标、近期训练情况和器械整理。先维持基础量，再按每 7 天反馈调整。下面的资料支持总体原则或动作参考，不代表对个人计划的专业审核。</p>${(state.program?.sources||knowledge?.sources||[]).map(source=>`<div class="meal-detail"><a class="link" href="${escapeHTML(source.url)}" target="_blank" rel="noopener">${escapeHTML(source.title)}</a><p>${escapeHTML(source.scope)}</p></div>`).join('')}<p class="health-line">内容版本 ${escapeHTML(knowledge?.version||'reference-2026-11-07')}。专业审核和示范视频仍待补齐。</p>`);break;case'record-history':{const res=await localFetch('/api/history');const data=await res.json();if(!res.ok)throw new Error(data.error||'历史记录暂不可用');const labels={'ai-program-confirm':'确认启用 DeepSeek 方案','reset-program':'重置训练计划','import':'恢复本机备份','cycle-plan-confirm':'确认周期训练计划','/api/profile':'修改个人资料','/api/records':'更新训练记录','/api/session':'训练计时操作','/api/review':'更新身体反馈','/api/plans/generate':'生成计划草稿','/api/plans/confirm':'确认训练计划','/api/programs/start':'启用 28 天训练阶段','/api/programs/activate-prepared':'保存对话资料并启用阶段'};openSheet('记录修改历史',data.history.length?data.history.map(h=>`<div class="meal-detail"><h3>${labels[h.operation]||'更新记录'}</h3><p>版本 ${h.revision} · ${escapeHTML(new Date(h.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</p></div>`).join(''):'<p class="sheet-intro">还没有记录，真实进度从第一次操作开始。</p>');break;}case'navigate':navigate(b.dataset.page);break;case'toggle':if(key>todayKey){toast('还没到训练日期，可以先查看动作');break;}await toggleTask(key,id);if(sheet.open)dayDetail(key);break;case'task':taskDetail(key,id);break;case'edit-record':if(key<=todayKey)showRecordForm(key,id);break;case'finish-task':if(key>todayKey)break;if(isDone(key,id)){await toggleTask(key,id);closeSheet();break;}showRecordForm(key,id);break;case'close':closeSheet();break;case'timer':startTimer();break;case'celebrate':toast('今天的目标已完成，好好休息！');break;case'meal':stopTimer();mealDetail(b.dataset.meal,key||todayKey);break;case'edit':editProfile(b.dataset.field);break;case'select-day':selectedKey=key;render();break;case'week':weekOffset=Math.max(-8,Math.min(8,weekOffset+Number(b.dataset.offset)));selectedKey=dateKey(addDays(monday,weekOffset*7));render();break;case'current-week':weekOffset=0;selectedKey=todayKey;render();break;case'next-week':weekOffset=1;selectedKey=dateKey(addDays(monday,7));navigate('plan');break;case'review':reviewForm();break;case'day-detail':dayDetail(key);break;}}catch(error){toast(error.message||'操作失败，请重试');}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['profile-form','review-form','finish-form','program-form','cycle-generation-form'].includes(form.id))return;e.preventDefault();if(aiRequestController||firstGenerationFlow.busy)return;if(!form.checkValidity()){const invalid=form.querySelector(':invalid');showFormError(form,'请检查'+(invalid?.closest('label')?.querySelector('span')?.textContent||'必填信息')+'，按字段要求填写后重试');invalid?.focus();return;}const data=new FormData(form);const submitButton=form.querySelector('[type=submit]');if(submitButton)submitButton.disabled=true;try{
if(form.id==='program-form'){const dataObject=Object.fromEntries(data.entries()),start=dataObject.start,generation=dataObject.generation,accessCode=dataObject.accessCode,consent=data.get('aiConsent')==='on';for(const k of ['start','generation','accessCode','aiConsent'])delete dataObject[k];for(const k of ['age','height','weight','duration'])dataObject[k]=Number(dataObject[k]);dataObject.runningKm=dataObject.runningKm===''?null:Number(dataObject.runningKm);dataObject.days=data.getAll('days').map(Number);if(!dataObject.days.length)throw new Error('请至少选择一天方便训练的日期');if(generation==='DeepSeek 个性化方案'){await generateDeepSeekPlan(form,{start,profile:{...state.profile,...dataObject},consent,accessCode});}else{const profile={...state.profile,...dataObject},draft=rulesWeek(start,profile);showPlanPreview({start,profile,consent:true},draft,{engine:'rules'});}}
else if(form.id==='profile-form'){const field=form.dataset.field,update=Object.fromEntries(data.entries());if(field==='basic'){if(!update.name.trim())throw new Error('请输入你的称呼');update.name=update.name.trim();for(const key of ['height','weight','age'])update[key]=Number(update[key]);update.runningKm=update.runningKm===''?null:Number(update.runningKm);}if(field==='schedule'){update.days=data.getAll('days').map(Number);update.duration=Number(update.duration);if(!update.days.length)throw new Error('请至少选择一个训练日');}if(field==='reminder'){update.reminder=update.enabled==='no'?'关闭':update.reminder;delete update.enabled;}await mutate('profile',{profile:update});closeSheet();toast('个人信息已保存，已有计划保留，可在“计划”中重新生成');}
else if(form.id==='review-form'){const review=Object.fromEntries(data.entries());review.weight=Number(review.weight);const cycleIndex=Number(form.dataset.cycle);await mutate('review',{review,cycleIndex});closeSheet();if(review.recovery==='有疼痛或不适'){toast('反馈已保存，请先确认恢复情况，暂不自动规划');}else if(state.program&&cycleIndex<3)cycleGenerateForm(cycleIndex+1);else toast('阶段反馈已保存，可以回顾本阶段进展');}
else if(form.id==='cycle-generation-form'){const index=Number(form.dataset.index);if(data.get('generation')==='本机规则参考'){const draft=localCycleDraft(state,index);showPlanPreview(draft.data,draft.raw,{engine:'rules'});}else{const request=cyclePlanningData(state,index,data.get('aiConsent')==='on');await generateDeepSeekPlan(form,{...request,accessCode:data.get('accessCode')});}}
else{const key=form.dataset.key,id=form.dataset.id;if(key>todayKey)return;const raw=data.get('minutes'),actual={};for(const [name,value]of data.entries())if(name.startsWith('actual_')&&value!=='')actual[name.slice(7)]=Number(value);await mutate('records',{date:key,id,done:true,minutes:raw===''?null:Number(raw),actual,effort:data.get('effort'),source:'manual'});closeSheet();toast('已保存手动训练记录');}
}catch(error){showFormError(form,error.message||'保存失败，请重试');}finally{if(submitButton)submitButton.disabled=false;}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['today','plan','mine'].includes(p)){page=p;render();}});
render();
loadState();

let pendingBackup=null;
function backupCard(){return `<section class="card"><h2>本机数据与备份</h2><p class="sheet-intro" style="margin:12px 0">记录仅保存在当前浏览器，不自动跨设备同步。清理浏览器数据前，请导出备份。备份含个人资料和训练记录，请自行妥善保管。</p><div class="sheet-actions"><button class="secondary blue" data-action="backup-export">导出 JSON 备份</button><button class="primary" data-action="backup-import">导入备份</button></div>${hasUpgradeBackup(browserStorage)?'<button class="link" style="margin-top:12px" data-action="upgrade-restore">恢复升级前记录</button>':''}<input id="backup-file" type="file" accept=".json,application/json" hidden></section>`;}
function exportBackup(){const value=readStore(browserStorage);const blob=new Blob([JSON.stringify({...value,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='qinglian-'+todayKey+'.backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，请妥善保管');}
document.addEventListener('change',async e=>{if(e.target.id!=='backup-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>8000000)throw new Error('备份文件过大');const {validateBackup}=await import('./src/local-store.mjs');pendingBackup=validateBackup(JSON.parse(await file.text()));openSheet('确认恢复备份',`<p class="sheet-intro">将恢复所选备份中的个人资料、阶段和训练记录，并替换当前浏览器中的记录。请先导出当前数据，保留可恢复副本。</p><div class="sheet-actions"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="backup-confirm">确认恢复备份</button></div>`);}catch(error){toast(error.message||'备份读取失败，原记录未改变');}e.target.value='';});
window.addEventListener('storage',e=>{if(e.key==='qinglian-local-v1')loadState();});

function onboardingPage(){return `${header('开始你的训练','先认识你，再安排适合的节奏')}<section class="card onboarding-card"><div class="detail-badge">${icon('user')}第一次使用</div><h2>用自己的资料，准备一份计划</h2><p>填写年龄、身高体重、目标、器械和每周可训练日期。按你的条件组合 28 天基础参考，进度从零开始。</p><ol class="steps"><li>填写个人信息与身体限制</li><li>生成每 7 天一个周期的训练安排</li><li>每天打卡，每周期记录身体反馈</li></ol><button class="primary" data-action="program-setup">填写资料，生成我的计划</button><p class="health-line">无需登录，资料只保存在当前浏览器；计划先预览、确认后使用，未经过独立专业审核。</p></section>${backupCard()}${hasResetBackup(browserStorage)?`<section class="card"><button class="link" data-action="reset-plan-restore">恢复重置前的计划与记录</button></section>`:''}`;}
function trainingDaysField(){return `<div class="field"><span>每周方便训练的日期（至少一天）</span><div class="day-checkboxes">${['一','二','三','四','五','六','日'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${state.profile.days.includes(i)?'checked':''}><span>周${d}</span></label>`).join('')}</div></div>`;}
function showFormError(form,message){let el=form.querySelector('.form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.append(el);}el.hidden=false;el.textContent=message;el.scrollIntoView({block:'center',behavior:'smooth'});}

function resetPlanCard(){return `<section class="card"><h2>训练计划管理</h2><p class="health-line">重置后清除当前计划和本阶段训练进度，保留个人资料，重新生成计划。重置前会在本机保留一份可恢复的记录。</p><button class="secondary reset-plan-button" style="width:100%;margin-top:15px" data-action="reset-plan">重置训练计划</button>${hasResetBackup(browserStorage)?'<button class="link" style="margin-top:12px" data-action="reset-plan-restore">恢复重置前的计划与记录</button>':''}</section>`;}
function confirmPlanReset(){openSheet('重置训练计划？',`<p class="sheet-intro">将清除当前 28 天计划、计划草稿、打卡进度、身体反馈与训练计时。个人资料会保留。页面重新载入后，你可以确认资料并生成新计划。</p><p class="health-line">本机将保留最近一次重置前的完整记录，可在引导页或“我的”中恢复；也可先导出 JSON 备份。</p><p id="reset-error" class="form-error" role="alert" hidden></p><div class="sheet-actions"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="reset-plan-confirm">确认重置并重新载入</button></div>`);}
function confirmResetRestore(){openSheet('恢复重置前的记录？',`<p class="sheet-intro">将用最近一次重置前保存的本机备份，替换当前计划和记录。需要保留当前数据时，请先导出备份。</p><p id="reset-error" class="form-error" role="alert" hidden></p><div class="sheet-actions"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="reset-plan-restore-confirm">确认恢复</button></div>`);}
function showResetError(message){const el=document.getElementById('reset-error');if(el){el.hidden=false;el.textContent=message;}else toast(message);}

function aiGenerationFields(){return AI_API_BASE?`${select('generation','计划生成方式','DeepSeek 个性化方案',['DeepSeek 个性化方案','本机规则参考'])}${input('accessCode','AI 内测邀请码（不是 DeepSeek 密钥）','','password','autocomplete="off" maxlength="128"')}<label class="consent-row"><input type="checkbox" name="aiConsent">我同意将年龄、身高体重、目标、运动与跑步基础、器械、可训练时间、无伤病状态及饮食偏好发送给 DeepSeek，仅用于本次方案生成；不发送称呼、联系方式、历史记录及训练描述自由文本。</label><p class="health-line">AI 会先生成预览，确认后才启用。动作名称与讲解固定，训练组次和时长按资料安排；不合格时自动修正，最多尝试 4 次，可能需要约 3 分钟。餐饮仍需自行核对过敏原。</p>`:'<p class="health-line">当前使用本机规则参考；DeepSeek 服务配置后可选择 AI 方案。</p>';}
function cycleGenerateForm(index){
 const cycle=state.program?.cycles[index];if(!cycle||index<1||index>3)return;
 if(!state.reviews[cycle.start]){reviewForm(index-1);return;}
 try{cyclePlanningData(state,index,true);}catch(error){toast(error.message);return;}
 openSheet('生成第 '+(index+1)+' 周期',`<p class="sheet-intro">${cycle.start}—${cycle.end}。根据当前资料、上一周期反馈和完成摘要编排，只更新此周期；确认前原安排保留。</p><form id="cycle-generation-form" data-index="${index}">${select('generation','生成方式','DeepSeek 个性化方案',['DeepSeek 个性化方案','本机规则参考'])}${input('accessCode','AI 内测邀请码','','password','autocomplete="off"')}<label class="consent-row"><input type="checkbox" name="aiConsent">我同意将必要个人资料、上一周期的难度与恢复反馈、完成项数、已记录时长和距离摘要发送给 DeepSeek；不发送称呼、备注、逐项历史记录。</label><p class="health-line">固定动作库 ${LIBRARY_VERSION}；失败时最多自动尝试4次。生成结果需要你确认。</p><div class="sheet-actions"><button class="secondary" type="button" data-action="close">取消</button><button class="primary" type="submit">生成周期预览</button></div></form>`);
}
function showPlanPreview(data,raw,metadata={}){
 const input=planningInput({...data,consent:true}),week=validateAIWeek(raw,input.profile,input.start,input);
 const temporary=programFromWeek(data.start,input.profile,week,{engine:metadata.engine||'deepseek',model:metadata.model});
 const days=temporary.cycles[0].days.map(d=>({...d,tasks:d.tasks.map(t=>resolveStandardTask(t,temporary))}));
 const {accessCode,...safeData}=data;pendingAI={...safeData,raw,model:metadata.model,engine:metadata.engine||'deepseek',revision:state.revision};
 openSheet('预览训练方案',draftPreview({title:data.purpose==='cycle'?state.program.title:week.title,reason:week.reason,days,engine:pendingAI.engine,cycleIndex:data.purpose==='cycle'?data.cycleIndex:null,attempts:metadata.generation?.attempts,formatDose:t=>taskPrescription(t,temporary)}));
}
async function generateDeepSeekPlan(form,data){
 if(aiRequestController||firstGenerationFlow.busy)return;
 if(!AI_API_BASE)throw new Error('DeepSeek 服务尚未接入');
 if(state.program&&data.purpose!=='cycle')throw new Error('已有训练阶段，请在周期反馈后调整未来安排，或备份并重置');
 const input=planningInput(data);if(!data.accessCode?.trim())throw new Error('请输入 AI 内测邀请码，不要填写模型密钥');
 const base=new URL(AI_API_BASE);if(base.protocol!=='https:')throw new Error('AI 服务地址必须使用 HTTPS');
 const revision=state.revision,programId=state.program?.id,button=form.querySelector('[type=submit]'),label=button.textContent;
 const initial=!state.program&&data.purpose!=='cycle';
 const operation=async()=>{
  button.disabled=true;button.textContent='正在生成并校验，请稍候…';
  const controller=new AbortController();aiRequestController=controller;let timedOut=false;const timeout=setTimeout(()=>{timedOut=true;controller.abort();},GENERATION_POLICY.clientTimeoutMs);
  try{
   const res=await fetch(new URL('/generate',base),{method:'POST',headers:{'Content-Type':'application/json','X-Access-Code':data.accessCode.trim()},body:JSON.stringify({...input,consent:true,requestId:uniqueId()}),signal:controller.signal,credentials:'omit',redirect:'error'});
   let response;try{response=await res.json();}catch(error){if(controller.signal.aborted)throw error;throw new Error('未收到完整可读取的方案，请稍后重新尝试。');}if(!res.ok)throw new Error(response.error||'生成失败，原计划保留');
   if(controller.signal.aborted)throw new DOMException('Aborted','AbortError');
   const current=readStore(browserStorage);if(current.state.revision!==revision||current.state.program?.id!==programId)throw new Error('资料或记录已在其他页面改变，请返回检查资料后重新生成');
   showPlanPreview(data,response.result,{model:response.model,engine:'deepseek',generation:response.generation});
  }catch(error){
   if(controller.signal.aborted||error.name==='AbortError')throw new Error(timedOut?'等待已超时，尚未启用计划。请稍后重新尝试。':'生成已取消，原计划未改变');
   if(error instanceof TypeError)throw new Error('网络连接中断，未能获取完整方案。请检查网络后重试。');
   throw error;
  }finally{clearTimeout(timeout);if(aiRequestController===controller)aiRequestController=null;button.textContent=label;button.disabled=false;}
 };
 if(initial){initialGeneration={form,data};await firstGenerationFlow.run(operation);}
 else await operation();
}
